  await page.locator('[data-billing=\"monthly\"]').click();
  if(await page.locator('[data-price=\"team\"]').textContent() "'!== '"'9' || await page.locator('[data-price=\"business\"]').textContent() "'!== '"'16') throw new Error('Monthly prices incorrect');
  await page.locator('summary').first().click();
  if("'!await page.locator('"'details').first().getAttribute('open') && await page.locator('details').first().getAttribute('open') "'!== '"'') throw new Error('FAQ failed');
  await page.locator('summary').first().click();
  await page.locator('#trial-email').fill('engineer@example.com');
  await page.locator('#trial-form button').click();
  if("'!await page.locator('"'#account-dialog').isVisible()) throw new Error('Trial dialog did not open');
  if(await page.locator('#account-email').inputValue() "'!== '"'engineer@example.com') throw new Error('Email not carried over');
  await page.locator('#account-submit').click();
  if("'!await page.locator('"'#account-message').textContent()) throw new Error('Missing form feedback');
  await page.keyboard.press('Escape');
  await page.locator('[data-sign-in]').first().click();
  if(await page.locator('#dialog-title').textContent() "'!== '"'Welcome back.') throw new Error('Sign in dialog failed');
  await page.keyboard.press('Escape');
  await page.setViewportSize({width:390,height:844});
  await page.evaluate(()=>window.scrollTo({top:0,behavior:'instant'}));
  await page.screenshot({path:'/private/tmp/rotaline-mobile.png',fullPage:true});
  console.log('Mobile:',await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,overflowing:[...document.querySelectorAll('body *')].filter(e=>{const r=e.getBoundingClientRect();return r.width>0 && (r.right>innerWidth+1||r.left< -1) && getComputedStyle(e).position"'!=='"'absolute'}).map(e=>e.className).filter(e=>typeof e==='string')})));
  await page.locator('.menu-button').click();
  if(await page.locator('.menu-button').getAttribute('aria-expanded') "'!== '"'true' || "'!await page.locator('"'#mobile-nav').isVisible()) throw new Error('Mobile navigation failed');
  await page.locator('#mobile-nav a[href=\"#pricing\"]').click();
  if(await page.locator('.menu-button').getAttribute('aria-expanded') "'!== '"'false') throw new Error('Mobile menu did not close');
  console.log('PASS: pricing, FAQ, signup validation flow, sign in, mobile navigation. JavaScript errors:', errors);
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
NODE"

