/bin/zsh -lc "/opt/homebrew/bin/node <<'NODE'
const fs=require('node:fs');
const vm=require('node:vm');
const assert=require('node:assert/strict');
const {parseHTML}=require('/opt/homebrew/lib/node_modules/clawdbot/node_modules/linkedom');
const html=fs.readFileSync('index.html','utf8');
const {document,window}=parseHTML(html);
const script=document.querySelector('script').textContent;
new vm.Script(script);
const dialog=document.querySelector('#account-dialog');
dialog.showModal=()=>dialog.setAttribute('open','');
dialog.close=()=>dialog.removeAttribute('open');
const context=vm.createContext({document,window,console});
vm.runInContext(script,context);
assert.equal(document.querySelectorAll('main > section').length,10);
assert.equal(document.querySelectorAll('.feature-grid article').length,6);
assert.equal(document.querySelectorAll('.step').length,3);
assert.equal(document.querySelectorAll('.price-card').length,3);
assert.equal(document.querySelectorAll('details').length,5);
assert.equal(document.querySelectorAll('img,script[src]').length,0);
const ids=[...document.querySelectorAll('[id]')].map(e=>e.id);
assert.equal(new Set(ids).size,ids.length);
for(const link of document.querySelectorAll('a[href"'^="#"], use[href''^="#"]'"')) {
 const id=link.getAttribute('href').slice(1);
 if(id) assert(document.getElementById(id),'Missing target '+id);
}
for(const [period,team,business] of [['annual','7','13'],['monthly','9','16']]) {
 document.querySelector('[data-billing=\"'+period+'\"]').click();
 assert.equal(document.querySelector('[data-price=\"team\"]').textContent,team);
 assert.equal(document.querySelector('[data-price=\"business\"]').textContent,business);
 assert.equal(document.querySelector('[data-billing=\"'+period+'\"]').getAttribute('aria-pressed'),'true');
}
const menu=document.querySelector('.menu-button');
menu.click();assert.equal(menu.getAttribute('aria-expanded'),'true');
document.querySelector('#mobile-nav a').click();assert.equal(menu.getAttribute('aria-expanded'),'false');
document.querySelector('#trial-email').value='engineer@example.com';
document.querySelector('#trial-form').dispatchEvent(new window.Event('submit',{cancelable:true}));
assert(dialog.hasAttribute('open'));
assert.equal(document.querySelector('#account-email').value,'engineer@example.com');
document.querySelector('#account-form').dispatchEvent(new window.Event('submit',{cancelable:true}));
assert(document.querySelector('#account-message').textContent.includes('has not been sent or saved'));
document.querySelector('.dialog-close').click();assert("'!dialog.hasAttribute('"'open'));
document.querySelector('[data-sign-in]').click();assert.equal(document.querySelector('#dialog-title').textContent,'Welcome back.');
console.log('PASS: JavaScript syntax, section counts, unique IDs, inline artwork, fragment targets, both billing periods, mobile menu, trial email flow, dialog dismissal, and sign-in flow.');
NODE"

